// Keeps only invoices that are EXACTLY 7, 14 or 30 days overdue today,
// so each invoice gets at most one reminder per tier (no daily spam).
// Each tier has its own Hebrew message - edit the texts freely.

const REMINDERS = {
  7: (inv) => 'היי ' + inv.name + ', תזכורת ידידותית: חשבונית מספר ' + inv.id + ' על סך ' + inv.amount + ' ₪ ממתינה לתשלום כבר שבוע. נשמח להסדרה בהקדם, תודה!',
  14: (inv) => 'שלום ' + inv.name + ', חשבונית מספר ' + inv.id + ' על סך ' + inv.amount + ' ₪ פתוחה כבר 14 יום. נודה לטיפולך. אם התשלום כבר בוצע, אפשר להתעלם מהודעה זו.',
  30: (inv) => 'שלום ' + inv.name + ', תזכורת אחרונה: חשבונית מספר ' + inv.id + ' על סך ' + inv.amount + ' ₪ פתוחה מזה 30 יום. נבקש להסדיר את התשלום עוד היום. לשאלות אנחנו זמינים כאן.',
};

function parseDate(v) {
  if (!v) return null;
  const s = String(v).trim();
  let d = DateTime.fromISO(s);
  if (!d.isValid) d = DateTime.fromFormat(s, 'dd/MM/yyyy');
  if (!d.isValid) d = DateTime.fromFormat(s, 'd/M/yyyy');
  if (!d.isValid) d = DateTime.fromFormat(s, 'MM/dd/yyyy');
  return d.isValid ? d.startOf('day') : null;
}

function toChatId(phone) {
  let digits = String(phone ?? '').replace(/\D/g, '');
  if (digits.startsWith('0')) digits = '972' + digits.slice(1);
  if (!digits.startsWith('972')) digits = '972' + digits;
  return digits + '@c.us';
}

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const due = parseDate(row.DueDate);
  if (!due) continue;
  const daysOverdue = Math.floor($today.diff(due, 'days').days);
  const buildMessage = REMINDERS[daysOverdue];
  if (!buildMessage) continue; // not exactly 7/14/30 days overdue today

  const inv = { id: row.InvoiceID ?? '', name: row.CustomerName ?? '', amount: row.Amount ?? '' };

  out.push({
    json: {
      InvoiceID: inv.id,
      CustomerName: inv.name,
      Amount: inv.amount,
      daysOverdue,
      tier: 'reminder-' + daysOverdue,
      chatId: toChatId(row.Phone),
      message: buildMessage(inv),
    },
  });
}
return out;
